import type { TabIconProps } from "./tab/tab.types";

import { forwardRef } from "react";
import { clsx } from "clsx";

import { TabClasses } from "./tab/tab.styles";

export const TabIcon = forwardRef<HTMLDivElement, TabIconProps>(({ className, ...props }, ref) => {
  const iconClasses = clsx(TabClasses.icon, className);

  return <div ref={ref} className={iconClasses} {...props} />;
});

TabIcon.displayName = "Tab.Icon";
